/**
 * 𝌋 TD613 · Boundary Attempt Graph (The Shadow Graph Engine)
 * 
 * Formal implementation of the prospective Wild Field hypothesis:
 * Distinguishes 6 explicit epistemic relation states:
 * 1. ADMITTED: Formally verified and registered in graph
 * 2. ATTEMPTED_REJECTED: Generated by instrument/cue, but rejected by admission criteria
 * 3. NEVER_GENERATED: Ground-truth unreached relation
 * 4. WITHHELD_LACK_OF_EVIDENCE: Candidate below warrant ceiling
 * 5. WITHDRAWN_SCOPE_CHANGE: Formerly admitted, dropped upon context withdrawal
 * 6. AWAITING_UNRESOLVED_EXTERNAL: Expected object gap awaiting external admission
 * 
 * Invariant: Attempt(u, v) does NOT imply Existence(v) or Warrant(u -> v).
 */

import crypto from 'node:crypto';

export const RELATION_STATES = {
  ADMITTED: 'ADMITTED',
  ATTEMPTED_REJECTED: 'ATTEMPTED_REJECTED',
  NEVER_GENERATED: 'NEVER_GENERATED',
  WITHHELD_LACK_OF_EVIDENCE: 'WITHHELD_LACK_OF_EVIDENCE',
  WITHDRAWN_SCOPE_CHANGE: 'WITHDRAWN_SCOPE_CHANGE',
  AWAITING_UNRESOLVED_EXTERNAL: 'AWAITING_UNRESOLVED_EXTERNAL',
};

export class BoundaryAttemptGraph {
  constructor() {
    this.nodes = new Map(); // id -> { id, admitted: boolean, metadata }
    this.edges = new Map(); // key -> { from, to, relation_type, state, reason, warrant, provenance, history: [] }
    this.attemptLog = [];
  }

  registerNode(nodeId, metadata = {}, admitted = true) {
    this.nodes.set(nodeId, {
      id: nodeId,
      admitted,
      metadata,
      registered_at: new Date().toISOString(),
    });
  }

  isNodeAdmitted(nodeId) {
    const n = this.nodes.get(nodeId);
    return Boolean(n && n.admitted);
  }

  recordAttempt({ from, to, relation_type, proposed_warrant, provenance = 'CUE_HARVEST' }) {
    const key = `${from}->${to}:${relation_type}`;
    const timestamp = new Date().toISOString();

    const fromAdmitted = this.isNodeAdmitted(from);
    const toAdmitted = this.isNodeAdmitted(to);

    let state = RELATION_STATES.ADMITTED;
    let reason = 'ALL_ENDPOINTS_AND_CRITERIA_VERIFIED';

    if (!fromAdmitted) {
      state = RELATION_STATES.ATTEMPTED_REJECTED;
      reason = `SOURCE_ENDPOINT_UNADMITTED: ${from}`;
    } else if (!toAdmitted) {
      // Check if target is known as an expected object
      const targetNode = this.nodes.get(to);
      if (targetNode && targetNode.metadata.expected_gap) {
        state = RELATION_STATES.AWAITING_UNRESOLVED_EXTERNAL;
        reason = `TARGET_EXPECTED_BUT_UNRESOLVED: ${to}`;
      } else {
        state = RELATION_STATES.ATTEMPTED_REJECTED;
        reason = `TARGET_ENDPOINT_UNADMITTED: ${to}`;
      }
    } else if (proposed_warrant === 'UNWARRANTED_NOISE') {
      state = RELATION_STATES.ATTEMPTED_REJECTED;
      reason = 'UNWARRANTED_COOCCURRENCE_REJECTED';
    } else if (proposed_warrant === 'PREEXISTING_CHRONOLOGY') {
      state = RELATION_STATES.ATTEMPTED_REJECTED;
      reason = 'CHRONOLOGICAL_INVERSION_BLOCKED';
    } else if (proposed_warrant === 'BELOW_EVIDENCE_CEILING') {
      state = RELATION_STATES.WITHHELD_LACK_OF_EVIDENCE;
      reason = 'INSUFFICIENT_EVIDENCE_FOR_ADMISSION';
    }

    const edgeRecord = {
      from,
      to,
      relation_type,
      state,
      reason,
      warrant: state === RELATION_STATES.ADMITTED ? proposed_warrant : null,
      provenance,
      recorded_at: timestamp,
      history: [
        {
          state,
          reason,
          timestamp,
        },
      ],
    };

    this.edges.set(key, edgeRecord);
    this.attemptLog.push({ from, to, relation_type, state, reason, timestamp });

    return edgeRecord;
  }

  withdrawNode(nodeId, reason = 'EXPLICIT_SOURCE_WITHDRAWAL') {
    const node = this.nodes.get(nodeId);
    if (!node) return;
    node.admitted = false;
    node.withdrawn_at = new Date().toISOString();

    for (const [key, edge] of this.edges.entries()) {
      if ((edge.from === nodeId || edge.to === nodeId) && edge.state === RELATION_STATES.ADMITTED) {
        edge.state = RELATION_STATES.WITHDRAWN_SCOPE_CHANGE;
        edge.reason = `${reason}: dependent on withdrawn node ${nodeId}`;
        edge.history.push({
          state: RELATION_STATES.WITHDRAWN_SCOPE_CHANGE,
          reason: edge.reason,
          timestamp: new Date().toISOString(),
        });
      }
    }
  }

  /**
   * Late admission of a previously missing node:
   * Re-evaluates all historical attempts in the Shadow Graph that were previously rejected or awaiting.
   */
  admitDelayedNode(nodeId, metadata = {}) {
    this.registerNode(nodeId, metadata, true);
    const recovered = [];

    for (const [key, edge] of this.edges.entries()) {
      if (edge.to === nodeId && (edge.state === RELATION_STATES.ATTEMPTED_REJECTED || edge.state === RELATION_STATES.AWAITING_UNRESOLVED_EXTERNAL)) {
        if (this.isNodeAdmitted(edge.from)) {
          edge.state = RELATION_STATES.ADMITTED;
          edge.reason = 'TARGET_SUBSEQUENTLY_ADMITTED_RECOVERY';
          edge.warrant = 'RECOVERED_HISTORICAL_ATTEMPT';
          edge.history.push({
            state: RELATION_STATES.ADMITTED,
            reason: edge.reason,
            timestamp: new Date().toISOString(),
          });
          recovered.push(edge);
        }
      }
    }
    return recovered;
  }

  getEdgesByState(state) {
    const list = [];
    for (const edge of this.edges.values()) {
      if (edge.state === state) list.push(edge);
    }
    return list;
  }

  getSummary() {
    const summary = {};
    for (const s of Object.values(RELATION_STATES)) {
      summary[s] = 0;
    }
    for (const edge of this.edges.values()) {
      summary[edge.state] = (summary[edge.state] || 0) + 1;
    }
    return {
      total_nodes: this.nodes.size,
      admitted_nodes: Array.from(this.nodes.values()).filter(n => n.admitted).length,
      total_edges_tracked: this.edges.size,
      edge_counts_by_state: summary,
      attempt_log_length: this.attemptLog.length,
    };
  }
}
